2.2 From a GFF3 (NCBI/Prokka)
The GFF3 file contains the Geneid info information as locus_tag, which we can parse along with other useful information from the attributes column.

# Set up your R environment and read the GFF3 file. Adapt based on the GFF3 name and location
library(tidyverse)
library(here)

GENOMES_DIR &lt;- here("inst/extdata/genomes")
GENOME_NAME &lt;- "GCF_000013465.1"

gff_file &lt;- file.path(GENOMES_DIR, paste0(GENOME_NAME, ".gff"))

# Read the GFF3 file into a data frame
gff_df &lt;- read_delim(
  gff_file,
  delim = "\t",
  col_names = c("seqname", "source", "feature", "start", "end", "score", "strand", "frame", "attributes"),
  comment = "#",
  show_col_types = FALSE
)

# Filter for CDS (protein-coding genes)
gff_cds &lt;- gff_df |&gt;
  filter(feature == "CDS")

# Function to parse the attributes column of GFF3
parse_gff3_attributes &lt;- function(attributes_string) {
  pairs &lt;- str_split(attributes_string, ";")[[1]]

  attr_list &lt;- list()

  for (pair in pairs) {
    if (pair == "") next

    parts &lt;- str_split(pair, "=", n = 2)[[1]]

    if (length(parts) == 2) {
      key &lt;- parts[1]
      value &lt;- parts[2]
      attr_list[[key]] &lt;- value
    }
  }

  return(attr_list)
}

# Apply the parsing function to the attributes column and create new columns for each key
annotations &lt;- gff_cds |&gt;
  rowwise() |&gt;
  mutate(attr_list = list(parse_gff3_attributes(attributes)))  |&gt;
  ungroup() |&gt;
  unnest_wider(attr_list, names_repair = "universal") |&gt; # Unnest all key=value pairs as columns
  select(-attributes) |&gt;
  rename(Geneid = locus_tag) # Required column for CONTENTO

# Replace commas in GO-related annotation fields with "!!!" to be used in multiple groupings in functional analysis
annotations &lt;- annotations |&gt;
  mutate(across(c(Ontology_term, go_function, go_process, go_component), ~ gsub(",", "!!!", .x)))

# Aggregate CDS fragments into gene-level annotations (handles programmed frameshifts)
annotations &lt;- annotations |&gt;
  group_by(Geneid) |&gt;
  summarise(
    start  = min(start),
    end    = max(end),
    strand = unique(strand),   # should be invariant per gene
    across(
      -c(start, end, strand, frame),
      first
    ),
    .groups = "drop"
  )

# Sanity check: Ensure there are no duplicated Gene IDs
sum(duplicated(annotations$Geneid))

# Save the annotations to a CSV/RDS file
write_csv(annotations, file.path(GENOMES_DIR, paste0(GENOME_NAME, "_annot.csv")))
saveRDS(annotations, file.path(GENOMES_DIR, paste0(GENOME_NAME, "_annot.rds")))

Step 4. Differential Expression Analysis
The design captures all the variables of interest.

# DESeq design 
dds &lt;- DESeqDataSetFromTximport(txi,
                                colData = meta,
                                design = ~ virus + exp)

# Run DESeq
dds &lt;- DESeq(dds)


Generate Contrast Results
This function runs the DESeq2 results() and lfcShrink() functions for a given contrast or coefficient, returning a data frame with the results. It handles both types of contrasts (main effects and interaction terms) and adds the contrast name to the results for easier identification.

run_contrast_analysis &lt;- function(dds, contrast_name, contrast = NULL, coef = NULL) {
  if (!is.null(contrast)) {
    res &lt;- results(dds, contrast = contrast, alpha = 0.05)
    resLFC &lt;- lfcShrink(dds, contrast = contrast, type = "ashr")
  } else if (!is.null(coef)) {
    res &lt;- results(dds, name = coef, alpha = 0.05)
    resLFC &lt;- lfcShrink(dds, coef = coef, type = "ashr")
  } else {
    stop("Please provide either a 'contrast' or a 'coef'.")
  }

  res_df &lt;- as.data.frame(res)
  res_df$Geneid &lt;- rownames(res_df)
  res_df$contrast &lt;- contrast_name

  res_df$log2FoldChange_shrunk &lt;- as.data.frame(resLFC)$log2FoldChange[
    match(res_df$Geneid, rownames(resLFC))
  ]

  return(res_df)
}


contrasts_df &lt;- run_contrast_analysis(dds, contrast_name = "VirusTvsF", coef = "virus_TRUE_vs_FALSE")







IMPORTANT:



CONTENTO requires generic column names so it works with any DE tool, not just DESeq2. Required: log2FC, stat, padj. Optional: log2FC_shrunk. DESeq2’s results() already outputs stat and padj with the right names — only log2FoldChange (and log2FoldChange_shrunk) need renaming.



contrasts_df &lt;- contrasts_df |&gt;
  dplyr::rename(log2FC = log2FoldChange, log2FC_shrunk = log2FoldChange_shrunk)
